// ── The verifier/solver gap — the essence of P vs NP ──────────────
//
// VERIFIER: polynomial time O(n) — checks a proposed solution
// SOLVER:   exponential time O(2^n) — must search for the solution
//
// This gap is what NP is all about.

// ── SAT verifier (polynomial) ──────────────────────────────────────
// Conjunctive Normal Form (CNF): AND of clauses, each clause = OR of literals.
// Literal: positive int = variable index (true), negative = negated (false).
function verifySAT(clauses, assignment) {
  // O(clauses * literals_per_clause) — polynomial
  return clauses.every(clause =>
    clause.some(lit => {
      const idx = Math.abs(lit);
      return lit > 0 ? assignment[idx] : !assignment[idx];
    })
  );
}

// Formula: (x1 ∨ x2) ∧ (¬x1 ∨ x3) ∧ (¬x2 ∨ ¬x3)
const clauses = [[1, 2], [-1, 3], [-2, -3]];

// Verification is O(n) — instant
console.log(verifySAT(clauses, { 1: true,  2: false, 3: true  })); // true  ✓
console.log(verifySAT(clauses, { 1: true,  2: true,  3: true  })); // false — (¬x2 ∨ ¬x3) fails
console.log(verifySAT(clauses, { 1: false, 2: false, 3: false })); // false — (¬x1 ∨ x3) fails

// ── SAT solver (exponential) ───────────────────────────────────────
// Try ALL 2^n assignments. No polynomial shortcut is known.
function solveSAT(clauses, numVars) {
  for (let mask = 0; mask < (1 << numVars); mask++) {
    const assignment = {};
    for (let i = 1; i <= numVars; i++) {
      assignment[i] = Boolean(mask & (1 << (i - 1)));
    }
    if (verifySAT(clauses, assignment)) return assignment;
  }
  return null; // unsatisfiable
}

const solution = solveSAT(clauses, 3);
console.log(solution);
// { 1: false, 2: true, 3: false } or another valid assignment
// For 3 variables: 2^3=8 attempts — trivial
// For 100 variables: 2^100 ≈ 1.3 × 10^30 attempts — at 10^9 per second,
// about 4 × 10^13 years (thousands of times the age of the universe)

// ── Subset Sum: verifier vs. brute-force solver ────────────────────

// Verifier: polynomial (O(n·k) here) — check the subset is valid and sums to target
function verifySubsetSum(set, subset, target) {
  // Each element of subset must appear in set (allowing repeats if set has them)
  const setCopy = [...set];
  for (const x of subset) {
    const idx = setCopy.indexOf(x);
    if (idx === -1) return false; // element not in set
    setCopy.splice(idx, 1);       // consume it
  }
  const sum = subset.reduce((a, b) => a + b, 0);
  return sum === target;
}

const set = [3, 1, 4, 1, 5, 9, 2, 6];
console.log(verifySubsetSum(set, [3, 4, 9], 16));   // true  (3+4+9=16)
console.log(verifySubsetSum(set, [3, 4, 9], 17));   // false
console.log(verifySubsetSum(set, [1, 5, 9], 15));   // true  (1+5+9=15)

// Solver: O(2^n) — enumerate all 2^n subsets
function solveSubsetSum(set, target) {
  const n = set.length;
  for (let mask = 1; mask < (1 << n); mask++) {
    let sum = 0;
    const subset = [];
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        sum += set[i];
        subset.push(set[i]);
      }
    }
    if (sum === target) return subset;
  }
  return null;
}

console.log(solveSubsetSum(set, 16)); // e.g. [3, 4, 9]
console.log(solveSubsetSum(set, 99)); // null — no subset sums to 99

// ── Note: there IS a pseudo-polynomial O(n*target) DP solution ─────
// This is why Subset Sum is 'only' weakly NP-complete — the input
// numbers' magnitudes matter, not just their count.
// Strongly NP-complete problems (like TSP or 3-Partition) have no
// pseudo-polynomial algorithm unless P = NP.
function subsetSumDP(set, target) {
  const dp = new Array(target + 1).fill(false);
  dp[0] = true;
  for (const x of set) {
    // Traverse right-to-left to avoid using x twice
    for (let t = target; t >= x; t--) {
      if (dp[t - x]) dp[t] = true;
    }
  }
  return dp[target];
}
console.log(subsetSumDP(set, 16)); // true
console.log(subsetSumDP(set, 99)); // false

// ── Practical complexity: picking a strategy for an NP-hard problem ─
// A toy decision helper — the point is the order of questions, not the code.

function chooseStrategy({ problem, n, k }) {
  // 1. Tiny input? Exact exponential search is fine.
  if (n <= 20) {
    return `Exact search: 2^${n} = ${(2 ** n).toLocaleString()} candidates — feasible`;
  }
  // 2. A small natural parameter? Use a fixed-parameter (FPT) algorithm.
  if (problem === 'vertex-cover' && k !== undefined && k <= 30) {
    return `FPT O(2^k · n): 2^${k} · ${n} ≈ ${(2 ** k * n).toExponential(1)} steps — exact and feasible`;
  }
  // 3. Need a provable quality bound? Use an approximation algorithm.
  if (problem === 'vertex-cover') return '2-approximation: take both endpoints of uncovered edges, O(V + E)';
  if (problem === 'metric-tsp')   return 'Christofides: ≤ 1.5 × optimal, O(n^3)';
  // 4. SAT-like constraints? Hand them to a modern CDCL solver.
  if (problem === 'sat') return 'CDCL SAT solver (Kissat, CaDiCaL): exponential worst case, often fast in practice';
  return 'Look for special structure, or use heuristics / local search';
}

console.log(chooseStrategy({ problem: 'sat', n: 15 }));
// Exact search: 2^15 = 32,768 candidates — feasible
console.log(chooseStrategy({ problem: 'vertex-cover', n: 50000, k: 15 }));
// FPT O(2^k · n): 2^15 · 50000 ≈ 1.6e+9 steps — exact and feasible
console.log(chooseStrategy({ problem: 'vertex-cover', n: 50000 }));
// 2-approximation: take both endpoints of uncovered edges, O(V + E)
console.log(chooseStrategy({ problem: 'metric-tsp', n: 1000 }));
// Christofides: ≤ 1.5 × optimal, O(n^3)

// ── 2-SAT is in P: implication graph + SCCs, O(V + E) ─────────────
// Each clause (a ∨ b) becomes two implications: ¬a → b and ¬b → a.
// The formula is UNSATISFIABLE iff some variable x has x and ¬x in the
// same strongly connected component (each would force the other).
// 3-SAT has no such structure and is NP-complete.
console.log('2-SAT: P (implication graph + SCC). 3-SAT: NP-complete.');
